pub(crate) fn panics_blocks(expr: &Expr) -> Vec<&Block> {
    let mut out: Vec<&Block> = vec![];
    match expr {
        Expr::Block(block, _) => { out.push(block); },
        Expr::AsyncGroup(block, _, _, _, _) => { out.push(block); },
        Expr::Unsafe(block, _) => { out.push(block); },
        Expr::Overlap(block, _) => { out.push(block); },
        Expr::Closure { body, .. } => { out.push(body); },
        Expr::If { then_branch, else_branch, .. } => {
            out.push(then_branch);
            if else_branch.is_some() { out.push(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return out }); }
        },
        Expr::TryCatch { handler, .. } => { out.push(handler); },
        Expr::Select(arms, _) => { for arm in arms.iter() { out.extend(check_visit_block_one(&arm.body)); } },
        _ => { },
    }
    out
}

pub(crate) fn panics_call(expr: &Expr, func: &Expr, items: &[Spanned<Item>], names: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, reach: &mut PanicReach) {
    match func {
        Expr::Variable(symbol, _) => {
            let symbol = *symbol;
            let written = names.resolve(symbol);
            if !own.functions.contains_key(written) {
                if written == "panic" || written == "assume" {
                    reach.sure = true;
                    return;
                }
                if written == "assert" { return; }
            }
        },
        _ => { },
    }
    let callee = match callee_of(names, expr, own, library, items) { Some(__nikaia_value) => __nikaia_value, None => return };
    match callee {
        Callee::Own(ref name) => { reach.calls.insert(name.to_string()); },
        Callee::Library { ref key, .. } => { panics_absorb(&nikaia_std::index::or(match (*nikaia_std::index::get(&library.functions, key)).as_ref().map(|__nikaia_it| &__nikaia_it.panics) {
            Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
            None => None,
        }, || Panics::Unknown), reach); },
        Callee::Opaque(_) => { reach.unknown = true; },
        Callee::Method => { },
    }
}

